onKey(" ", async () => {
  // lift the left arm and wave
  await part("left arm").turnTo(150);
  say("Hi!", 2);
  await part("left arm").wiggle(3);
  await part("left arm").turnTo(0);
  // head over to the tree
  await goTo(thing("tree-3"), 7);
});

forever(async () => {
  // Look ahead for something red
  const seen = await look(8);
  if (seen && is(seen, "red")) {
    play("honk");
    await move(-5, 7); // back up
  }
});

const rainbow = ["red", "orange", "yellow", "green", "blue", "purple", "pink"];
let busy = false;

onClick(async () => {
  if (busy) return; // don't start again while floating
  busy = true;
  gravity(0); // everything floats!
  play("whoosh");
  say("Floaty time!", 2);
  await wait(5);
  gravity(1); // back to normal
  play("drum");
  // drop a bunch of rainbow bricks
  for (let i = 0; i < 14; i++) {
    spawn({ color: rainbow[i % rainbow.length], size: "2x2", at: place(random(-10, 10), random(-10, 10)) });
    await wait(0.15);
  }
  play("yay");
  busy = false;
});
